int main(){const uint32_t C[]={0,4,8,12,16,20,24,28,32,36,40,44,48,52,56,60};uint64_t cases=0,chains=0;for(uint32_t target=0;target<32;target++)for(uint32_t lane=0;lane<32;lane++)for(uint32_t r=0;r<16;r++)for(uint32_t hm=0;hm<2;hm++){const uint32_t nx=(target<<15)|(r<<11)|(hm<<9);const uint32_t key=((nx>>9)&0x7fdu)-(lane<<6);for(int i=0;i<16;i++){bool ref=lane==target&&hm==0&&r==(uint32_t)i;if(ref!=(key==C[i]))return 1;cases++;}}for(int n:{0,1,31,32})for(uint32_t seed=0;seed<64;seed++){uint32_t a[32][16],b[32][16];for(int l=0;l<32;l++)for(int i=0;i<16;i++)a[l][i]=b[l][i]=0x9e3779b9u*(1+l*16+i);for(int j=0;j<n;j++){uint32_t nx=(((j+seed)%32)<<15)|(((j/3+seed)%16)<<11)|((j%2)<<10)|(((j+seed)%3==0)<<9)|((j*13+seed)%128);uint32_t xr=(nx&127u)<<(8+((nx>>10)&1)*16);for(uint32_t lane=0;lane<32;lane++){uint32_t key=((nx>>9)&0x7fdu)-(lane<<6);for(int i=0;i<16;i++){if(lane==((nx>>15)&31)&&((nx>>9)&1)==0&&i==((nx>>11)&15))a[lane][i]^=xr;if(key==C[i])b[lane][i]^=xr;}}}for(int l=0;l<32;l++)for(int i=0;i<16;i++)if(a[l][i]!=b[l][i])return 2;chains++;}printf("%llu %llu\n",(unsigned long long)cases,(unsigned long long)chains);}
